def wf(*labels):
    return ("world_folk_objects.csv", lambda x: x["node_label"] in labels)


def ef_sub(s):
    return ("europe_folk_objects.csv", lambda x: s in x["node_key"])


def quran_early(x):
    yy = y(x)
    if not QURAN.search(x["label"]) or re.search(r"Calligraph|Muraqqa|Karahisari|lexicon", x["label"], re.I):
        return None
    if yy is not None and yy < 1000:
        return "Hijazi and early Kufic Qur'ans (7th–8th century)" if yy < 800 else "Abbasid Kufic Qur'ans (9th–10th century)"
    return None


def quran_illum(x):
    yy, s = y(x), o(x)
    if not QURAN.search(x["label"]) or re.search(r"Calligraph|Muraqqa|Karahisari|lexicon|Sana'a|Birmingham|Topkapi manuscript|Parisino|Mashhad", x["label"], re.I):
        return None
    if yy is not None and yy < 1000:
        return None
    if "mamluk" in s:
        return "Mamluk Qur'ans"
    if "ilkhan" in s:
        return "Ilkhanid Qur'ans"
    if "timurid" in s or "safavid" in s or "shiraz" in s or "herat" in s or "iran" in s:
        return "Timurid and Safavid Qur'ans"
    if "ottoman" in s or "istanbul" in s or "karaman" in s or "konya" in s:
        return "Ottoman and Anatolian Qur'ans"
    if "zirid" in s or "spain" in s or "tunisia" in s or "maghreb" in s or "palermo" in s:
        return "Maghribi and Andalusi Qur'ans"
    if "patani" in s or "gwalior" in s or "india" in s:
        return "South and Southeast Asian Qur'ans"
    return "Other and unlocalised Qur'ans"


Q_ORDER = ["Maghribi and Andalusi Qur'ans", "Mamluk Qur'ans", "Ilkhanid Qur'ans", "Timurid and Safavid Qur'ans", "Ottoman and Anatolian Qur'ans", "South and Southeast Asian Qur'ans", "Other and unlocalised Qur'ans"]

HEB = {"Hebrew manuscripts (unlocalised)": "Hebrew manuscripts, region unrecorded", "Hebrew: Ashkenazi": "Ashkenazi manuscripts", "Hebrew: Sephardi": "Sephardi manuscripts",
       "Hebrew: Italian": "Italian Hebrew manuscripts", "Hebrew: French / Provençal": "French and Provençal manuscripts", "Hebrew: Oriental (Mizrahi, Persian, Egyptian)": "Oriental Hebrew manuscripts",
       "Hebrew: Yemenite": "Yemenite manuscripts"}


def heb(x):
    if x["tradition"] not in HEB:
        return None
    if not (x["illuminated_class"] == "1" or re.search(r"Bible|Haggad|Mahzor|Machsor|Keter|Pentateuch|Miscellany|Psalter", x["label"]) or x["genres"]):
        return None
    if re.search(r"Papyrus|Scroll|Letter", x["label"]):
        return None
    return HEB[x["tradition"]]


def phase_by_year(ranges, undated):
    def f(x):
        yy = y(x)
        if yy is None:
            return undated
        for hi, g in ranges:
            if yy < hi:
                return g
        return ranges[-1][1]
    return f


